import { Platform } from 'react-native';
import { addDays, parseDate } from './format';

/**
 * Local trip reminders on the device (work offline, need no push server).
 * Server-side in-app reminders are generated by the generate_trip_reminders() DB function.
 */
async function mod() {
  if (Platform.OS === 'web') return null;
  return await import('expo-notifications');
}

export async function ensureNotificationPermission(): Promise<boolean> {
  try {
    const N = await mod();
    if (!N) return false;
    const cur = await N.getPermissionsAsync();
    if (cur.granted) return true;
    const req = await N.requestPermissionsAsync();
    return req.granted;
  } catch {
    return false;
  }
}

export async function scheduleTripReminders(tripId: string, destination: string, startDate: string) {
  try {
    const N = await mod();
    if (!N) return;
    if (!(await ensureNotificationPermission())) return;
    N.setNotificationHandler({
      handleNotification: async () => ({ shouldShowBanner: true, shouldShowList: true, shouldPlaySound: false, shouldSetBadge: false }),
    });
    await cancelTripReminders(tripId);
    const plan: [number, string, string][] = [
      [-7, `Your ${destination} trip starts in 7 days`, 'Review your itinerary and finish your checklist.'],
      [-1, `Your ${destination} trip starts tomorrow`, 'Have a great trip! Open Travel OS for your plan.'],
    ];
    for (const [off, title, body] of plan) {
      const d = parseDate(addDays(startDate, off));
      d.setHours(9, 0, 0, 0);
      if (d.getTime() <= Date.now()) continue;
      await N.scheduleNotificationAsync({
        identifier: `trip-${tripId}-${off}`,
        content: { title, body, data: { tripId } },
        trigger: { type: N.SchedulableTriggerInputTypes.DATE, date: d },
      });
    }
  } catch {
    /* reminders are best-effort */
  }
}

export async function cancelTripReminders(tripId: string) {
  try {
    const N = await mod();
    if (!N) return;
    for (const off of [-7, -1]) await N.cancelScheduledNotificationAsync(`trip-${tripId}-${off}`);
  } catch {
    /* ignore */
  }
}
